"use client";

import * as React from "react";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { fieldOpen, formFieldBase, formFieldSingleLine } from "./_shared";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "./command";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

const sizes = [
  { value: "small", label: "Small, 2 cores" },
  { value: "medium", label: "Medium, 4 cores" },
  { value: "large", label: "Large, 8 cores" },
  { value: "xlarge", label: "Extra large, 16 cores" },
  { value: "gpu", label: "GPU, 1 card" },
];

/** Mallow combobox demo: a white field that opens a searchable list as wide as the field. */
export function ComboboxDemo() {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");
  const selected = sizes.find((size) => size.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        role="combobox"
        aria-expanded={open}
        data-slot="combobox-trigger"
        className={cn(
          formFieldBase,
          formFieldSingleLine,
          "w-64 cursor-default items-center justify-between gap-2 text-start",
          fieldOpen,
          !selected && "text-muted-foreground",
        )}
      >
        <span className="truncate">{selected ? selected.label : "Select a size"}</span>
        <Icon icon="iconoir:nav-arrow-down" className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--anchor-width) gap-0 p-0">
        <Command className="bg-transparent shadow-none">
          <CommandInput placeholder="Search sizes" />
          <CommandList>
            <CommandEmpty>No size found.</CommandEmpty>
            <CommandGroup>
              {sizes.map((size) => (
                <CommandItem
                  key={size.value}
                  value={size.value}
                  onSelect={(currentValue: string) => {
                    setValue(currentValue === value ? "" : currentValue);
                    setOpen(false);
                  }}
                >
                  {size.label}
                  <Icon
                    icon="iconoir:check"
                    className={cn("ms-auto size-4 text-foreground", value === size.value ? "opacity-100" : "opacity-0")}
                    aria-hidden="true"
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
